SourceCode.Declaration:
/// <summary>
/// Script to clear security configuration objects from the xml file.
/// </summary>
final class METClearSecurityConfigScript
{
}

Method.Source:
/// <summary>
/// Main method.
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public static void main(Args _args)
{
    METClearSecurityConfigScript script= new METClearSecurityConfigScript();
    script.run();
}

/// <summary>
/// Runs the script.
/// </summary>
public void run()
{
    // Prompt the user to select the XML file from the client machine.
    str filePath = this.selectFile();

    if (!filePath)
    {
        warning("No file selected. Operation cancelled.");
        return;
    }

    this.parseAndDelete(filePath);
}

/// <summary>
/// Selects file.
/// </summary>
/// <returns>File.</returns>
private str selectFile()
{
    // The file is staged in temporary blob storage; retrieve the URL / path.
    FileUploadTemporaryStorageResult result = File::GetFileFromUser();

    if (!result || !result.getUploadStatus())
    {
        return '';
    }

    return result.getDownloadUrl();
}

/// <summary>
/// Parses and deletes objects.
/// </summary>
/// <param name = "_filePathOrUrl">Path.</param>
private void parseAndDelete(str _filePathOrUrl)
{
    XmlDocument  xmlDoc  = new XmlDocument();
    XmlNodeList  roleNodes;
    XmlNode      roleNode;
    XmlNode      taskNode;
    XmlNodeList  taskNodes;

    str          roleName;
    str          dutyName;
    int          roleCount;
    int          dutyCount;
    SecurityDuty duty;
    SecurityRole role;

    if (strStartsWith(_filePathOrUrl, "https://") ||
        strStartsWith(_filePathOrUrl, "http://"))
    {
        System.Net.WebClient webClient = new System.Net.WebClient();
        str xmlString = webClient.DownloadString(_filePathOrUrl);
        xmlDoc.loadXml(xmlString);
    }
    else
    {
        xmlDoc.load(_filePathOrUrl);
    }

    if (!xmlDoc)
    {
        error("Failed to load the XML file.");
        return;
    }

    roleNodes = xmlDoc.selectNodes(
        "//Record[@Name='UserSecGovProcessRoleView']");

    if (!roleNodes || roleNodes.length() == 0)
    {
        warning("No UserSecGovProcessRoleView records found in the file.");
        return;
    }

    info(strFmt("Processing file – found %1 Process Role record(s).",
                roleNodes.length()));
    info("=============================================================");

    for (int i = 0; i < roleNodes.length(); i++)
    {
        roleNode  = roleNodes.item(i);
        roleName  = this.getFieldValue(roleNode, "Name");
        roleCount++;

        info(strFmt("ROLE [%1]: %2", roleCount, roleName));

        // ----- XPath: child <Record Name="UserSecGovTaskScriptView"> -----
        taskNodes = roleNode.selectNodes(
            "Record[@Name='UserSecGovTaskScriptView']");

        if (taskNodes && taskNodes.length() > 0)
        {
            for (int j = 0; j < taskNodes.length(); j++)
            {
                taskNode = taskNodes.item(j);
                dutyName = this.getFieldValue(taskNode, "SecurityDuty");
                dutyCount++;

                delete_from duty 
                    where duty.Name == dutyName;

                if (dutyName)
                {
                    info(strFmt("    DUTY [%1]: %2", dutyCount, dutyName));
                }

            }
        }
    }

    delete_from role
         where role.Name == roleName;

    info(strFmt("Done. Total roles: %1 | Total task/duty rows: %2",
                roleCount, dutyCount));
}

/// <summary>
/// Returns field value.
/// </summary>
/// <param name = "_parentNode">Parent.</param>
/// <param name = "_fieldName">Field name.</param>
/// <returns>Field name.</returns>
private str getFieldValue(XmlNode _parentNode, str _fieldName)
{
    XmlNode fieldNode = _parentNode.selectSingleNode(
        strFmt("Field[@Name='%1']", _fieldName));

    if (fieldNode)
    {
        return fieldNode.text();
    }

    return '';
}
